import json
import logging
import os
from pathlib import Path
from typing import Any, Dict

logger = logging.getLogger(__name__)


class ConfigError(Exception):
    pass


def load_config(
    config_file: str,
    defaults: Dict[str, Any],
    env_prefix: str = ""
) -> Dict[str, Any]:
    """Load JSON config from disk, falling back to defaults if file is missing or invalid.

    Environment variables override config values when env_prefix is set (e.g., "APP"
    creates APP_PORT, APP_HOST, etc.).
    """
    config = defaults.copy()

    config_path = Path(config_file)
    if not config_path.exists():
        logger.info(f"Config file not found: {config_file}. Using defaults.")
    else:
        try:
            with open(config_path) as f:
                loaded = json.load(f)
        except json.JSONDecodeError as e:
            logger.warning(f"Malformed JSON in {config_file}: {e}. Using defaults.")
        except Exception as e:
            logger.warning(f"Error reading {config_file}: {e}. Using defaults.")
        else:
            if not isinstance(loaded, dict):
                logger.warning(f"Config is not a dict, got {type(loaded).__name__}. Using defaults.")
            else:
                config.update(loaded)

    if env_prefix:
        for key in config:
            env_var = f"{env_prefix.upper()}_{key.upper()}"
            if env_var in os.environ:
                config[key] = os.environ[env_var]

    if "port" in config:
        validate_port(config["port"])

    return config


def validate_port(port: Any) -> None:
    """Validate that port is an integer between 1024 and 65535."""
    if not isinstance(port, int) or isinstance(port, bool):
        raise ConfigError(f"port must be an integer, got {type(port).__name__}")

    if not 1024 <= port <= 65535:
        raise ConfigError(f"port must be between 1024 and 65535, got {port}")
